// === diskon.js ===
export function hitungDiskon(harga, persen) {
  const potongan = harga * persen / 100;
  return harga - potongan;
}
// === main.js ===
import { hitungDiskon } from "./diskon.js";
console.log(hitungDiskon(20000, 10));
console.log(hitungDiskon(50000, 25));
